{
  "title": "Discussion about living and working in Slovakia and Austria",
  "topics": [
    {
      "id": "living-abroad",
      "title": "People living or wanting to live abroad",
      "claims": [
        {
          "text": "Some members live in Bratislava or elsewhere in Slovakia",
          "evidence": [1]
        },
        {
          "text": "U2 mentions acquaintances abroad: @AndriiRaccoon in Austria and walternet134 in Poland",
          "evidence": [3]
        },
        {
          "text": "U3 says they have at least two acquaintances in Austria",
          "evidence": [12]
        },
        {
          "text": "U3 notes one acquaintance recently arrived in Austria and another has been there for several years",
          "evidence": [13]
        },
        {
          "text": "U3 has been in Austria since 17.11.2025",
          "evidence": [49]
        },
        {
          "text": "U1 has been in Slovakia for almost a year and does not speak the language",
          "evidence": [43]
        }
      ]
    },
    {
      "id": "job-search",
      "title": "Finding work abroad",
      "claims": [
        {
          "text": "U3 found a job in Austria within two months after sending about 100 applications, resulting in three interviews",
          "evidence": [21, 17]
        },
        {
          "text": "LinkedIn is recommended for job searching",
          "evidence": [18]
        },
        {
          "text": "Most vacancies (95%) require local language proficiency",
          "evidence": [26]
        },
        {
          "text": "Lack of local language can lead to being filtered out",
          "evidence": [27]
        },
        {
          "text": "There are cases where candidates with little language skill are still hired",
          "evidence": [29]
        },
        {
          "text": "Higher education rarely matters for hiring decisions",
          "evidence": [32]
        }
      ]
    },
    {
      "id": "language-requirements",
      "title": "Language needs for work and daily life",
      "claims": [
        {
          "text": "German is the primary language spoken in Austria; English is also used",
          "evidence": [14, 15]
        },
        {
          "text": "Employers often request B2 level language, sometimes B1, but certificates are usually not required",
          "evidence": [46]
        },
        {
          "text": "U1 feels uncomfortable with the language barrier outside of work",
          "evidence": [51, 52]
        },
        {
          "text": "U3 started learning Slovak recently to feel more comfortable in the city",
          "evidence": [47]
        }
      ]
    },
    {
      "id": "salary-expectations",
      "title": "Salary expectations abroad",
      "claims": [
        {
          "text": "U3 says salaries in Europe are generally higher than in Ukraine but few notice",
          "evidence": [35]
        },
        {
          "text": "U3 accepted a minimal salary after stating they needed any job",
          "evidence": [37]
        },
        {
          "text": "U3 mentions having 3 years of experience but still received low offers",
          "evidence": [23]
        }
      ]
    },
    {
      "id": "events-and-networking",
      "title": "Events and community building",
      "claims": [
        {
          "text": "U1 attended an anime festival to meet people but faced language barrier",
          "evidence": [50, 51]
        },
        {
          "text": "U3 proposes attending a tech event in Warsaw (wawtech.io/summer)",
          "evidence": [59]
        }
      ]
    }
  ],
  "decisions": [],
  "openQuestions": [
    {
      "text": "U1 asks U3 whether they plan to stay in Austria",
      "evidence": [58]
    }
  ]
}
